        // Top half: initially all black
        for (int i = 0; i < 50; i++) {
            Arrays.fill(g[i], '#');
        }
        // Bottom half: initially all white
        for (int i = 50; i < 100; i++) {
            Arrays.fill(g[i], '.');
        }

        // We already have:
        // black components = 1 (top half)
        // white components = 1 (bottom half)
        //
        // Add (A-1) isolated white cells in the black half
        // Add (B-1) isolated black cells in the white half
        //
        // Place them every other row/column so they don't touch.

        int needWhite = A - 1;
        for (int i = 0; i < 50 && needWhite > 0; i += 2) {
            for (int j = 0; j < 100 && needWhite > 0; j += 2) {
                g[i][j] = '.';
                needWhite--;
            }
        }

        int needBlack = B - 1;
        for (int i = 51; i < 100 && needBlack > 0; i += 2) {
            for (int j = 0; j < 100 && needBlack > 0; j += 2) {
                g[i][j] = '#';
                needBlack--;
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append(h).append(' ').append(w).append('\n');
        for (int i = 0; i < h; i++) {
            sb.append(g[i]).append('\n');
